//! CodexAstraUlt: Original explicit-hint and resolved-code fixtures. These
//! tests neither read private titles nor mutate HOME or shared environment state.

use super::*;
use crate::image::Segment;
use std::collections::BTreeMap;
use std::sync::atomic::AtomicUsize;

const BASE: u32 = 0x0010_0000;

// CodexAstraUlt: Fresh, owned fixture paths permit parallel tests and remove
// only the files this fixture created, including during an assertion unwind.
struct Fixture {
    input: PathBuf,
    root: PathBuf,
}

impl Fixture {
    fn new() -> Self {
        static NEXT: AtomicUsize = AtomicUsize::new(0);
        let sequence = NEXT.fetch_add(1, Ordering::Relaxed);
        let name = format!("resolved-{sequence}");
        let root = std::env::temp_dir().join(format!("3dsrecomp-{name}-{}", std::process::id()));
        std::fs::create_dir(&root).unwrap();
        let input = crate::rom::tests::rom(&name, &0xE12F_FF1Eu32.to_le_bytes(), &[]);
        Self { input, root }
    }

    fn title(&self) -> Title {
        Title::load(&self.input).unwrap()
    }
}

impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.input);
        let _ = std::fs::remove_dir_all(&self.root);
    }
}

// CodexAstraUlt: The first word is an ARM return; the otherwise-unreferenced
// Thumb movs/return must be admitted only when the explicit hint requests it.
fn program() -> Program {
    Program {
        text: Segment {
            base: BASE,
            bytes: [0xE12F_FF1Eu32, 0x4770_202A]
                .into_iter()
                .flat_map(u32::to_le_bytes)
                .collect(),
        },
        seeds: vec![(BASE, Source::Entry)],
        slots: None,
    }
}

// CodexAstraUlt: Compare the actual generated bytes under all stable filenames,
// not just a file count that could hide changed lowering or origin metadata.
fn files(dir: &Path) -> BTreeMap<String, Vec<u8>> {
    std::fs::read_dir(dir)
        .unwrap()
        .map(|entry| {
            let entry = entry.unwrap();
            (
                entry.file_name().into_string().unwrap(),
                std::fs::read(entry.path()).unwrap(),
            )
        })
        .collect()
}

// CodexAstraUlt: Panicking source callbacks prove a policy never consults an
// excluded source, even if that source would contain valid extra addresses.
#[test]
fn explicit_policies_do_not_consult_ambient_hints() {
    let unexpected = || -> Vec<u32> { panic!("excluded hint source was read") };
    assert!(select_hints(
        HintMode::Selected(HintPolicy::Disabled),
        unexpected,
        unexpected
    )
    .is_empty());
    assert_eq!(
        select_hints(
            HintMode::Selected(HintPolicy::Explicit(&[BASE + 5])),
            unexpected,
            unexpected
        ),
        [BASE + 5]
    );
    assert_eq!(
        select_hints(
            HintMode::Selected(HintPolicy::BundledOnly),
            unexpected,
            || vec![BASE + 9]
        ),
        [BASE + 9]
    );
    assert_eq!(
        select_hints(HintMode::Legacy, || vec![BASE + 5], || vec![BASE + 9]),
        [BASE + 5, BASE + 9]
    );
}

// CodexAstraUlt: A known unreferenced Thumb function tests actual rediscovery;
// duplicate/out-of-range hints cannot add duplicate or unrelated functions.
#[test]
fn selected_hints_preserve_filtering_and_admit_the_requested_function() {
    let fixture = Fixture::new();
    let title = fixture.title();
    let mut programs = vec![("executable".into(), program())];
    let mut analyses = vec![discover::analyze(&programs[0].1)];
    assert!(!analyses[0].functions.contains_key(&(BASE + 4)));
    assert_eq!(
        apply_selected_hints(
            &title,
            &mut programs,
            &mut analyses,
            HintMode::Selected(HintPolicy::Disabled)
        ),
        0
    );
    assert!(!analyses[0].functions.contains_key(&(BASE + 4)));
    let hints = [BASE + 5, BASE + 5, BASE + 0x100, BASE];
    assert_eq!(
        apply_selected_hints(
            &title,
            &mut programs,
            &mut analyses,
            HintMode::Selected(HintPolicy::Explicit(&hints))
        ),
        1
    );
    let function = &analyses[0].functions[&(BASE + 4)];
    assert_eq!(function.mode, Mode::Thumb);
    assert_eq!(function.source, Source::Hint);
    assert_eq!(function.instructions, [BASE + 4, BASE + 6]);
    assert_eq!(
        programs[0]
            .1
            .seeds
            .iter()
            .filter(|(_, source)| *source == Source::Hint)
            .count(),
        1
    );
}

// CodexAstraUlt: Resolved generation must consume supplied programs directly
// instead of reopening/reconstructing the title's one-word executable. Disabled
// and an explicitly empty list produce the same complete output on repeat.
#[test]
fn resolved_generation_uses_supplied_programs_reproducibly() {
    let fixture = Fixture::new();
    let generate = |name: &str, policy| {
        let generated = generate_resolved(
            fixture.title(),
            vec![("executable".into(), program())],
            fixture.root.join(name),
            policy,
            &|_| {},
        )
        .unwrap();
        assert!(!generated.sources.is_empty());
        for source in &generated.sources {
            assert!(generated.dir.join(source).is_file());
        }
        files(&generated.dir)
    };
    let first = generate("first", HintPolicy::Disabled);
    assert_eq!(first, generate("second", HintPolicy::Disabled));
    assert_eq!(first, generate("empty", HintPolicy::Explicit(&[])));
    let hinted = generate("hinted", HintPolicy::Explicit(&[BASE + 5]));
    assert_ne!(first, hinted);
    let entries = String::from_utf8(hinted["entries.c"].clone()).unwrap();
    assert!(entries.contains("0x00100005u"), "{entries}");
    assert!(entries.contains("recomp_generation = 3u"), "{entries}");
}

// CodexAstraUlt: Invalid resolved identities must fail before any output write;
// duplicate/unsafe module names could otherwise make lookup ambiguous or emit C.
#[test]
fn resolved_generation_rejects_invalid_program_names_before_writing() {
    let fixture = Fixture::new();
    let invalid_names: &[&[&str]] = &[
        &[],
        &["module"],
        &["executable", "executable"],
        &["executable", "module", "module"],
        &["executable", ""],
        &["executable", "bad\"name"],
        &["executable", "bad\\name"],
        &["executable", "trigraph??/name"],
        &["executable", "line\nbreak"],
        &["executable", "nul\0byte"],
        &["executable", "módulo"],
    ];
    for (index, names) in invalid_names.iter().enumerate() {
        let output = fixture.root.join(format!("rejected-{index}"));
        let programs = names
            .iter()
            .map(|name| (name.to_string(), program()))
            .collect();
        assert!(generate_resolved(
            fixture.title(),
            programs,
            output.clone(),
            HintPolicy::Disabled,
            &|_| {}
        )
        .is_err());
        assert!(!output.exists());
    }
    let output = fixture.root.join("rejected-long");
    assert!(generate_resolved(
        fixture.title(),
        vec![
            ("executable".into(), program()),
            ("x".repeat(256), program())
        ],
        output.clone(),
        HintPolicy::Disabled,
        &|_| {},
    )
    .is_err());
    assert!(!output.exists());
}

// CodexAstraUlt: The streaming adapter owns no filesystem writes. Its accepted
// content, source order and final event match the historical disk writer.
#[test]
fn resolved_streaming_preserves_output_and_reports_only_accepted_files() {
    let fixture = Fixture::new();
    let reference = generate_resolved(
        fixture.title(),
        vec![("executable".into(), program())],
        fixture.root.join("reference"),
        HintPolicy::Explicit(&[BASE + 5]),
        &|_| {},
    )
    .unwrap();
    let output = fixture.root.join("sink-only");
    let events = std::sync::Mutex::new(Vec::new());
    let mut accepted = BTreeMap::new();
    let generated = generate_resolved_to(
        fixture.title(),
        vec![("executable".into(), program())],
        output.clone(),
        HintPolicy::Explicit(&[BASE + 5]),
        &|event| events.lock().unwrap().push(event),
        &mut |name, bytes| {
            assert!(accepted.insert(name.to_owned(), bytes.to_vec()).is_none());
            Ok(())
        },
    )
    .unwrap();
    assert!(!output.exists());
    assert_eq!(accepted, files(&reference.dir));
    assert_eq!(generated.sources, reference.sources);
    assert_eq!(generated.dir, output);
    assert_eq!(
        events.into_inner().unwrap().last(),
        Some(&Event::Generated {
            files: accepted.len(),
            bytes: accepted.values().map(Vec::len).sum(),
            overrides: 0,
        })
    );
}

// CodexAstraUlt: A sink rejection remains the first concrete error and cannot
// be followed by further callbacks, directory creation or a Generated event.
#[test]
fn resolved_streaming_rejection_never_reports_success() {
    let fixture = Fixture::new();
    let output = fixture.root.join("rejected-sink");
    let events = std::sync::Mutex::new(Vec::new());
    let mut seen = Vec::new();
    let result = generate_resolved_to(
        fixture.title(),
        vec![("executable".into(), program())],
        output.clone(),
        HintPolicy::Disabled,
        &|event| events.lock().unwrap().push(event),
        &mut |name, _| {
            seen.push(name.to_owned());
            if name == "functions.h" {
                Err("fixture rejected header".into())
            } else {
                Ok(())
            }
        },
    );
    assert!(matches!(result, Err(ref message) if message == "fixture rejected header"));
    assert_eq!(seen, ["recomp.h", "functions.h"]);
    assert!(!output.exists());
    assert!(!events
        .into_inner()
        .unwrap()
        .iter()
        .any(|event| matches!(event, Event::Generated { .. })));
}
